/* logo(g, x, baseline, xHeight, {color}) → geometry {x,base,xh,s,wordW,w,top,bottom,tittle:{cx,cy,w,h},clear}
   x is the left edge of the m. Draws the wordmark only. */
function logo(g,x,base,xh,o={}){ const s=xh/LOGO.xh; if(!_lp) _lp=new Path2D(LOGO.d);
  g.save(); g.translate(x-LOGO.x0*s, base-LOGO.base*s); g.scale(s,s); g.fillStyle=o.color||'#15181d'; g.fill(_lp,'evenodd'); g.restore();
  return logoGeo(x,base,xh); }
function logoGeo(x,base,xh){ const s=xh/LOGO.xh, X=v=>x+(v-LOGO.x0)*s, Y=v=>base-(LOGO.base-v)*s, T=LOGO.tittle;
  return {x,base,xh,s,wordW:(LOGO.right-LOGO.x0)*s, w:(LOGO.w-LOGO.x0)*s, top:Y(LOGO.asc), bottom:Y(LOGO.desc),
    tittle:{cx:(X(T.x0)+X(T.x1))/2, cy:(Y(T.y0)+Y(T.y1))/2, w:(T.x1-T.x0)*s, h:(T.y1-T.y0)*s}, clear:(T.y1-T.y0)*s}; }
